import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { 
  Database, 
  CheckCircle, 
  RefreshCw, 
  AlertCircle, 
  Link2, 
  Clock, 
  FileSpreadsheet, 
  UploadCloud,
  HelpCircle
} from 'lucide-react';

const ProductUpload = () => {
  const [activeTab, setActiveTab] = useState('sheets'); // 'sheets' or 'file'

  // Google Sheets state
  const [sheetUrl, setSheetUrl] = useState('');
  const [syncStatus, setSyncStatus] = useState(null);
  const [syncing, setSyncing] = useState(false);
  const [savingConfig, setSavingConfig] = useState(false);
  const [syncMessage, setSyncMessage] = useState({ text: '', type: '' });
  const [showHelp, setShowHelp] = useState(false);

  // Manual File Upload state
  const [file, setFile] = useState(null);
  const [uploading, setUploading] = useState(false);
  const [fileSuccessMsg, setFileSuccessMsg] = useState('');

  // Fetch Google Sheets Sync Status on mount
  const fetchSyncStatus = async () => {
    try {
      const response = await axios.get('http://localhost:5000/api/products/sync-status');
      setSyncStatus(response.data);
      if (response.data.googleSheetUrl) {
        setSheetUrl(response.data.googleSheetUrl);
      }
    } catch (error) {
      console.error('Error fetching sync status:', error);
    }
  };

  useEffect(() => {
    fetchSyncStatus();
  }, []);

  // Save Google Sheet URL configuration
  const handleSaveConfig = async () => {
    if (!sheetUrl.trim()) {
      alert('يرجى إدخال رابط Google Sheet أولاً');
      return;
    }

    setSavingConfig(true);
    setSyncMessage({ text: '', type: '' });
    try {
      await axios.post('http://localhost:5000/api/products/sheet-config', {
        googleSheetUrl: sheetUrl.trim(),
        autoSyncEnabled: true
      });
      setSyncMessage({ text: 'تم حفظ رابط Google Sheet بنجاح.', type: 'success' });
      await fetchSyncStatus();
    } catch (error) {
      console.error('Error saving sheet config:', error);
      setSyncMessage({ text: 'فشل حفظ إعدادات الرابط.', type: 'error' });
    } finally {
      setSavingConfig(false);
    }
  };

  // Immediate Sync from Google Sheets
  const handleSyncNow = async () => {
    if (!sheetUrl.trim()) {
      alert('يرجى إدخال رابط Google Sheet لبدء المزامنة');
      return;
    }

    setSyncing(true);
    setSyncMessage({ text: '', type: '' });
    try {
      const response = await axios.post('http://localhost:5000/api/products/sync-sheet', {
        sheetUrl: sheetUrl.trim()
      });
      setSyncMessage({ 
        text: `تمت المزامنة بنجاح! تم تحديث ${response.data.count || 0} منتج.`, 
        type: 'success' 
      });
      await fetchSyncStatus();
    } catch (error) {
      console.error('Error syncing products:', error);
      const errMsg = error.response?.data?.message || 'حدث خطأ أثناء مزامنة البيانات من جوجل شيت.';
      setSyncMessage({ text: errMsg, type: 'error' });
      await fetchSyncStatus();
    } finally {
      setSyncing(false);
    }
  };

  // Handle Manual File Upload
  const handleFileChange = (e) => {
    if (e.target.files && e.target.files.length > 0) {
      setFile(e.target.files[0]);
      setFileSuccessMsg('');
    }
  };

  const handleManualUpload = async () => {
    if (!file) return;

    const formData = new FormData();
    formData.append('file', file);

    setUploading(true);
    try {
      const response = await axios.post('http://localhost:5000/api/products/upload', formData, {
        headers: { 'Content-Type': 'multipart/form-data' }
      });
      setFileSuccessMsg(response.data.message);
      setFile(null);
      await fetchSyncStatus();
    } catch (error) {
      console.error('Error uploading product file:', error);
      alert('Error uploading product file');
    } finally {
      setUploading(false);
    }
  };

  // Handle Clear Master Data
  const handleDeleteMaster = async () => {
    if (window.confirm('هل أنت متأكد من مسح جميع بيانات المنتجات (Master Data)؟')) {
      try {
        await axios.delete('http://localhost:5000/api/products/all');
        alert('تم مسح جميع بيانات المنتجات بنجاح.');
        setSyncMessage({ text: 'تم تفريغ بيانات المنتجات.', type: 'info' });
        await fetchSyncStatus();
      } catch (error) {
        console.error('Error deleting master data:', error);
        alert('حدث خطأ أثناء مسح البيانات');
      }
    }
  };

  const formatDateTime = (dateString) => {
    if (!dateString) return 'لم تتم بعد';
    const d = new Date(dateString);
    return d.toLocaleString('ar-EG', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  return (
    <div className="bg-white rounded-2xl shadow-sm border border-slate-100 p-6 flex flex-col justify-center">
      {/* Header */}
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-2">
          <Database className="w-5 h-5 text-emerald-600" />
          <h3 className="text-lg font-bold text-slate-800">بيانات المنتجات والأحجام (Products CBM)</h3>
        </div>
        <button
          onClick={handleDeleteMaster}
          className="text-xs px-3 py-1.5 rounded-lg text-red-600 bg-red-50 hover:bg-red-100 font-medium transition-all border border-red-200"
          title="مسح جميع بيانات المنتجات"
        >
          مسح الكل (Clear)
        </button>
      </div>

      {/* Tabs */}
      <div className="flex bg-slate-100 p-1 rounded-xl mb-4 text-xs font-semibold">
        <button
          onClick={() => setActiveTab('sheets')}
          className={`flex-1 py-2 px-3 rounded-lg flex items-center justify-center gap-1.5 transition-all ${
            activeTab === 'sheets'
              ? 'bg-white text-emerald-700 shadow-sm font-bold'
              : 'text-slate-600 hover:text-slate-900'
          }`}
        >
          <FileSpreadsheet className="w-4 h-4 text-emerald-600" />
          <span>مزامنة Google Sheets (تلقائي)</span>
        </button>
        <button
          onClick={() => setActiveTab('file')}
          className={`flex-1 py-2 px-3 rounded-lg flex items-center justify-center gap-1.5 transition-all ${
            activeTab === 'file'
              ? 'bg-white text-emerald-700 shadow-sm font-bold'
              : 'text-slate-600 hover:text-slate-900'
          }`}
        >
          <UploadCloud className="w-4 h-4 text-slate-500" />
          <span>رفع ملف يدوي (Excel / CSV)</span>
        </button>
      </div>

      {/* Google Sheets Tab */}
      {activeTab === 'sheets' && (
        <div className="flex flex-col gap-3">
          {/* Schedule Banner */}
          <div className="flex items-center justify-between bg-emerald-50 border border-emerald-100 rounded-xl p-3 text-xs text-emerald-800">
            <div className="flex items-center gap-2">
              <Clock className="w-4 h-4 text-emerald-600 flex-shrink-0" />
              <span>
                <strong>التحديث التلقائي اليومي:</strong> مجدول يومياً في تمام الساعة <strong>06:00 صباحاً</strong>
              </span>
            </div>
            <button
              onClick={() => setShowHelp(!showHelp)}
              className="text-emerald-700 hover:text-emerald-900 flex items-center gap-1"
              title="طريقة إعداد الشيت"
            >
              <HelpCircle className="w-3.5 h-3.5" />
              تعليمات
            </button>
          </div>

          {/* Help box */}
          {showHelp && (
            <div className="bg-slate-50 border border-slate-200 rounded-xl p-3 text-xs text-slate-600 space-y-1">
              <p className="font-semibold text-slate-800">طريقة مشاركة Google Sheet:</p>
              <ol className="list-decimal list-inside space-y-0.5 text-slate-600">
                <li>افتح شيت المنتجات في Google Sheets.</li>
                <li>اضغط على زر <strong>Share (مشاركة)</strong> في الأعلى.</li>
                <li>غيّر الوصول العام إلى: <strong>Anyone with the link can view (أي شخص لديه الرابط يمكنه العرض)</strong>.</li>
                <li>انسخ الرابط والصقه في الحقل أدناه، ثم اضغط <strong>مزامنة الآن</strong>.</li>
              </ol>
            </div>
          )}

          {/* URL Input */}
          <div className="relative">
            <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
              <Link2 className="h-4 w-4 text-slate-400" />
            </div>
            <input
              type="url"
              value={sheetUrl}
              onChange={(e) => setSheetUrl(e.target.value)}
              placeholder="https://docs.google.com/spreadsheets/d/..."
              className="block w-full pl-9 pr-3 py-2.5 text-xs text-slate-800 bg-slate-50 border border-slate-200 rounded-xl focus:bg-white focus:outline-none focus:ring-2 focus:ring-emerald-500 focus:border-transparent transition-all"
            />
          </div>

          {/* Action buttons */}
          <div className="flex items-center gap-2">
            <button
              onClick={handleSyncNow}
              disabled={syncing || !sheetUrl.trim()}
              className={`flex-1 py-2.5 px-4 rounded-xl text-white font-semibold text-xs flex items-center justify-center gap-2 transition-all ${
                syncing || !sheetUrl.trim()
                  ? 'bg-slate-300 cursor-not-allowed'
                  : 'bg-emerald-600 hover:bg-emerald-700 shadow-md hover:shadow-emerald-200'
              }`}
            >
              <RefreshCw className={`w-3.5 h-3.5 ${syncing ? 'animate-spin' : ''}`} />
              {syncing ? 'جاري المزامنة...' : 'مزامنة الآن (Sync Now)'}
            </button>

            <button
              onClick={handleSaveConfig}
              disabled={savingConfig || !sheetUrl.trim()}
              className="py-2.5 px-3.5 rounded-xl text-slate-700 bg-slate-100 hover:bg-slate-200 font-semibold text-xs transition-all border border-slate-200"
              title="حفظ الرابط للتحديث اليومي التلقائي"
            >
              {savingConfig ? 'حفظ...' : 'حفظ الرابط'}
            </button>
          </div>

          {/* Sync Message Alert */}
          {syncMessage.text && (
            <div
              className={`p-2.5 rounded-xl text-xs flex items-start gap-2 ${
                syncMessage.type === 'success'
                  ? 'bg-emerald-50 text-emerald-800 border border-emerald-200'
                  : syncMessage.type === 'error'
                  ? 'bg-red-50 text-red-800 border border-red-200'
                  : 'bg-blue-50 text-blue-800 border border-blue-200'
              }`}
            >
              {syncMessage.type === 'success' ? (
                <CheckCircle className="w-4 h-4 flex-shrink-0 text-emerald-600 mt-0.5" />
              ) : (
                <AlertCircle className="w-4 h-4 flex-shrink-0 text-red-600 mt-0.5" />
              )}
              <span className="leading-snug">{syncMessage.text}</span>
            </div>
          )}

          {/* Status info footer */}
          {syncStatus && (
            <div className="bg-slate-50 border border-slate-100 rounded-xl p-2.5 flex items-center justify-between text-xs text-slate-500">
              <div className="flex items-center gap-1.5">
                <span
                  className={`w-2 h-2 rounded-full ${
                    syncStatus.lastSyncStatus === 'success'
                      ? 'bg-emerald-500'
                      : syncStatus.lastSyncStatus === 'error'
                      ? 'bg-red-500'
                      : syncStatus.lastSyncStatus === 'running'
                      ? 'bg-amber-500 animate-ping'
                      : 'bg-slate-400'
                  }`}
                />
                <span>آخر مزامنة: <strong>{formatDateTime(syncStatus.lastSyncAt)}</strong></span>
              </div>
              <div>
                إجمالي المنتجات: <strong className="text-slate-700">{syncStatus.totalProductsInDb || 0}</strong>
              </div>
            </div>
          )}
        </div>
      )}

      {/* Manual File Tab */}
      {activeTab === 'file' && (
        <div className="flex flex-col gap-3">
          <div>
            <label className="block w-full text-xs text-slate-500 file:mr-3 file:py-2 file:px-3 file:rounded-lg file:border-0 file:text-xs file:font-semibold file:bg-emerald-50 file:text-emerald-700 hover:file:bg-emerald-100 cursor-pointer border border-slate-200 rounded-xl p-1 bg-slate-50">
              <input 
                type="file" 
                accept=".csv, application/vnd.openxmlformats-officedocument.spreadsheetml.sheet, application/vnd.ms-excel" 
                onChange={handleFileChange}
                disabled={uploading}
                className="w-full"
              />
            </label>
          </div>

          <button
            onClick={handleManualUpload}
            disabled={!file || uploading}
            className={`py-2.5 px-4 rounded-xl text-white font-semibold text-xs transition-all ${
              !file || uploading 
                ? 'bg-slate-300 cursor-not-allowed' 
                : 'bg-emerald-600 hover:bg-emerald-700 shadow-md hover:shadow-emerald-200'
            }`}
          >
            {uploading ? 'جاري الرفع...' : 'رفع ملف Master Data'}
          </button>

          {fileSuccessMsg && (
            <div className="flex items-center gap-2 text-emerald-600 text-xs font-medium">
              <CheckCircle className="w-4 h-4" />
              {fileSuccessMsg}
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default ProductUpload;
